/**
 * Resolves whether the wide desktop modal should be applied: requires both the
 * integrator's own `wideDesktopModal` configuration AND the connectToken's
 * clientId being on the internal feature flag allowlist (see internalFeatureFlags.ts).
 * Returns `false` if the token is missing/invalid or the configuration wasn't requested.
 */
export declare function isWideDesktopModalEnabled(connectToken: string | undefined, wideDesktopModalConfig: boolean | undefined): boolean;
